-- 来源触发器保留原本地/版本语义，云在途由统一回执的来源围栏保护。
DROP TRIGGER IF EXISTS transfer_singer_source_revision$$
CREATE TRIGGER transfer_singer_source_revision BEFORE UPDATE ON singer_resources FOR EACH ROW
BEGIN
    IF NOT (NEW.singer_source_ref_id <=> OLD.singer_source_ref_id) OR NOT (CAST(NEW.resource_kind AS BINARY) <=> CAST(OLD.resource_kind AS BINARY)) OR NOT (CAST(NEW.remote_url AS BINARY) <=> CAST(OLD.remote_url AS BINARY)) THEN
        SET NEW.source_revision=GREATEST(NEW.source_revision,OLD.source_revision+1);
        IF OLD.status=1 THEN SET NEW.claim_generation=GREATEST(NEW.claim_generation,OLD.claim_generation+1),NEW.running_batch_id=NULL; END IF;
        IF NEW.status=1 THEN SET NEW.status=IF(OLD.local_content_generation>0 OR COALESCE(OLD.local_path,'')<>'',2,0); END IF;
        IF NOT (NEW.singer_source_ref_id <=> OLD.singer_source_ref_id) OR NOT (CAST(NEW.resource_kind AS BINARY) <=> CAST(OLD.resource_kind AS BINARY)) THEN
            SET NEW.content_generation=GREATEST(NEW.content_generation,OLD.content_generation+1);
            SET NEW.reference_sha256='',NEW.reference_size_bytes=0;
        END IF;
    END IF;
END$$

DROP TRIGGER IF EXISTS transfer_album_source_revision$$
CREATE TRIGGER transfer_album_source_revision BEFORE UPDATE ON album_resources FOR EACH ROW
BEGIN
    IF NOT (NEW.album_source_ref_id <=> OLD.album_source_ref_id) OR NOT (CAST(NEW.resource_kind AS BINARY) <=> CAST(OLD.resource_kind AS BINARY)) OR NOT (CAST(NEW.remote_url AS BINARY) <=> CAST(OLD.remote_url AS BINARY)) THEN
        SET NEW.source_revision=GREATEST(NEW.source_revision,OLD.source_revision+1);
        IF OLD.status=1 THEN SET NEW.claim_generation=GREATEST(NEW.claim_generation,OLD.claim_generation+1),NEW.running_batch_id=NULL; END IF;
        IF NEW.status=1 THEN SET NEW.status=IF(OLD.local_content_generation>0 OR COALESCE(OLD.local_path,'')<>'',2,0); END IF;
        IF NOT (NEW.album_source_ref_id <=> OLD.album_source_ref_id) OR NOT (CAST(NEW.resource_kind AS BINARY) <=> CAST(OLD.resource_kind AS BINARY)) THEN
            SET NEW.content_generation=GREATEST(NEW.content_generation,OLD.content_generation+1);
            SET NEW.reference_sha256='',NEW.reference_size_bytes=0;
        END IF;
    END IF;
END$$


DROP PROCEDURE IF EXISTS crawler_drop_cloud_v2913$$
CREATE PROCEDURE crawler_drop_cloud_v2913()
BEGIN
    DECLARE n INT DEFAULT 0;
    SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='album_resources' AND COLUMN_NAME REGEXP '^cloud_';
    IF n=13 THEN
        SET @retire_cloud_ddl=CONCAT('ALTER TABLE `album_resources` ',IF(EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='album_resources' AND INDEX_NAME='idx_album_resources_cloud_queue'),'DROP INDEX `idx_album_resources_cloud_queue`,',''),'DROP COLUMN `cloud_backend`,DROP COLUMN `cloud_path`,DROP COLUMN `cloud_size_bytes`,DROP COLUMN `cloud_checksum`,DROP COLUMN `cloud_status`,DROP COLUMN `cloud_uploaded_at`,DROP COLUMN `cloud_claim_generation`,DROP COLUMN `cloud_claimed_at`,DROP COLUMN `cloud_running_batch_id`,DROP COLUMN `cloud_error_category`,DROP COLUMN `cloud_result_code`,DROP COLUMN `cloud_last_error`,DROP COLUMN `cloud_attempt`');
        PREPARE retire_cloud_stmt FROM @retire_cloud_ddl;
        EXECUTE retire_cloud_stmt;
        DEALLOCATE PREPARE retire_cloud_stmt;
    END IF;
    SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='singer_resources' AND COLUMN_NAME REGEXP '^cloud_';
    IF n=13 THEN
        SET @retire_cloud_ddl=CONCAT('ALTER TABLE `singer_resources` ',IF(EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='singer_resources' AND INDEX_NAME='idx_singer_resources_cloud_queue'),'DROP INDEX `idx_singer_resources_cloud_queue`,',''),'DROP COLUMN `cloud_backend`,DROP COLUMN `cloud_path`,DROP COLUMN `cloud_size_bytes`,DROP COLUMN `cloud_checksum`,DROP COLUMN `cloud_status`,DROP COLUMN `cloud_uploaded_at`,DROP COLUMN `cloud_claim_generation`,DROP COLUMN `cloud_claimed_at`,DROP COLUMN `cloud_running_batch_id`,DROP COLUMN `cloud_error_category`,DROP COLUMN `cloud_result_code`,DROP COLUMN `cloud_last_error`,DROP COLUMN `cloud_attempt`');
        PREPARE retire_cloud_stmt FROM @retire_cloud_ddl;
        EXECUTE retire_cloud_stmt;
        DEALLOCATE PREPARE retire_cloud_stmt;
    END IF;
    SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='song_resource_artifacts' AND COLUMN_NAME REGEXP '^cloud_';
    IF n=2 THEN
        SET @retire_cloud_ddl='ALTER TABLE `song_resource_artifacts` DROP COLUMN `cloud_backend`,DROP COLUMN `cloud_path`';
        PREPARE retire_cloud_stmt FROM @retire_cloud_ddl;
        EXECUTE retire_cloud_stmt;
        DEALLOCATE PREPARE retire_cloud_stmt;
    END IF;
    SELECT COUNT(*) INTO n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='song_resources' AND COLUMN_NAME REGEXP '^cloud_';
    IF n=3 THEN
        SET @retire_cloud_ddl='ALTER TABLE `song_resources` DROP COLUMN `cloud_backend`,DROP COLUMN `cloud_path`,DROP COLUMN `cloud_uploaded_at`';
        PREPARE retire_cloud_stmt FROM @retire_cloud_ddl;
        EXECUTE retire_cloud_stmt;
        DEALLOCATE PREPARE retire_cloud_stmt;
    END IF;
END$$
CALL crawler_drop_cloud_v2913()$$
